-- No browser storage write policies: verified Next.js server operations only.
do $$declare t text;begin foreach t in array array['registrations','payments','submissions','claim_invoices','shipments'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename=t) then execute format('alter publication supabase_realtime add table %I',t);end if;end loop;end$$;
